style.css:
body {
    background: linear-gradient(
        135deg,
        #0b0b12,
        #171025,
        #0b0b12
    ) !important;
    color: #eee8ff;
}

/* Search fields only */
input,
textarea {
    background-color: #171222 !important;
    color: #f5efff !important;
    border: 1px solid #493361 !important;
    border-radius: 12px !important;
    transition: border-color 0.2s ease,
                box-shadow 0.2s ease;
}

/* Search field focus */
input:focus,
textarea:focus {
    border-color: #b477ff !important;
    box-shadow: 0 0 8px #8b5bc8 !important;
    outline: none !important;
}

/* Buttons */
button {
    border-radius: 10px !important;
    transition: background-color 0.2s ease,
                box-shadow 0.2s ease;
}

/* Button hover */
button:hover {
    box-shadow: 0 0 10px #8750bd !important;
}

/* Navigation and general panels */
nav,
header,
aside {
    border-color: #30223f !important;
}

/* Custom scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: #0b0b12;
}

::-webkit-scrollbar-thumb {
    background: #65418a;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #a66ce0;
}

/* Text selection */
::selection {
    background: #8050b5;
    color: #ffffff;
}
